import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"延迟物化","description":"","frontmatter":{"title":"延迟物化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/late-materialization.md","filePath":"cs/late-materialization.md","lastUpdated":1789023840000}'),h={name:"cs/late-materialization.md"};function E(_,a,m,u,B,A){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="延迟物化" tabindex="-1">延迟物化 <a class="header-anchor" href="#延迟物化" aria-label="Permalink to &quot;延迟物化&quot;">​</a></h1><div class="epigraph"><p>扫描先只碰过滤与连接键列，RID 或位置向量拖到需要投影时才解引用；列存上这是默认，行存上是少回表。</p><footer>—— 据 Abadi, Myers, DeWitt and Madden 列存物化策略；Boncz 等；覆盖索引对照</footer></div><p><a href="/cs/parallel-exchange">上一课</a>会把元组在工人间搬运。本课不选 broadcast。缺口是<strong>何时组装完整行</strong>：早物化（扫描时读出所有列）简单，shuffle 与哈希表变宽；迟物化（late materialization）只传递位置与少量键，谓词与连接之后再取投影列。执行引擎单元在此封口，存储进阶从缓冲池再开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>列存：各列分开。先读选择率高的列做过滤，幸存位置再取其他列，I/O 与解压都少。行存：覆盖索引已是一种迟物化（不回堆）；否则 RID 列表过滤后再堆取，可能随机 I/O 比早读整行更差——校准决定。</p><p>缺口是策略选择，不是新代数。连接：可用键列连接得到 RID 对，再取载荷列。聚合：只取分组键与聚合列。</p><p><span class="marginnote">Abadi et al. 比较 early/late materialization。PAX 把行组与列存折中，后课。本课执行策略与存储格式耦合，但语义仍是同一投影。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>位置列表（selection vector / RID 向量）在算子间传递。扫描接口：按列拉向量，按位置 gather。缓存：迟取可能打乱页顺序，要批量化 gather 成对页友好的顺序。</p><p>与向量化天然合一：批就是一段位置。编译生成 gather 循环。并行：shuffle 只发键+位置，载荷在目标节点本地读——存算分离时位置必须仍能寻址。</p>',10)),(e(),s(c,null,{default:r(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILT%5B%22%E8%BF%87%E6%BB%A4%E5%88%97%22%5D%20--%3E%20POS%5B%22%E5%B9%B8%E5%AD%98%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20POS%20--%3E%20JOIN%5B%22%E7%94%A8%E9%94%AE%E5%88%97%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20JOIN%20--%3E%20POS2%5B%22%E7%BB%93%E6%9E%9C%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20POS2%20--%3E%20PROJ%5B%22%E5%86%8D%E8%AF%BB%E6%8A%95%E5%BD%B1%E5%88%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>更新与 MVCC：位置必须绑定快照，版本回收不能在查询还拿着 RID 时物理重用——后课 MVCC GC。行存删除空洞使 RID 仍有效直到 vacuum。</p><p>代价：迟物化增加随机 gather；选择率高时早物化更好。优化器应估计幸存率再选策略，误差又回来了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 LRU-K 替换。也不把宽列数据库的列族当迟物化的同义词。执行引擎收口：从迭代器、向量、编译、排序、哈希、Grace、exchange 到物化时机。</p><p>后课默认：OLAP 列路径迟物化；点查行路径早读整行或覆盖索引。缓冲池下一课：页在内存里如何替换，迟 gather 打的就是它。</p><p>传递更窄的向量，是并行与列存的同一条减流量原则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>迟物化推迟投影列 I/O；高选择率时可能更差。</li><li>位置必须绑定快照，不能提前回收。</li><li>下一单元缓冲池 LRU-K / 2Q：页替换服务扫描与 gather。</li><li>出处：Abadi et al.；Boncz 等；覆盖索引对照。</li></ul>',9))])}const P=l(h,[["render",E]]);export{f as __pageData,P as default};
